package net.civeira.phylax.feature.observe.issue;

import java.util.Optional;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;

/**
 * Regular expressions written by people (fingerprint rules), evaluated in the writer: at most 200
 * characters, and a match that reads the text too many times (catastrophic backtracking) is stopped
 * and counts as no match, so a bad rule can never block the collector.
 */
public final class SafeRegex {

  public static final int MAX_LENGTH = 200;
  private static final int MAX_STEPS = 200_000;

  private SafeRegex() {}

  /** The compiled pattern, or empty if it is too long or invalid. */
  public static Optional<Pattern> compile(final String pattern) {
    if (null == pattern || pattern.isBlank() || pattern.length() > MAX_LENGTH) {
      return Optional.empty();
    }
    try {
      return Optional.of(Pattern.compile(pattern));
    } catch (PatternSyntaxException ex) {
      return Optional.empty();
    }
  }

  /** True if the pattern is found in the text within the step limit. */
  public static boolean find(final Pattern pattern, final String text) {
    if (null == text) {
      return false;
    }
    try {
      return pattern.matcher(new Bounded(text)).find();
    } catch (TooSlow ex) {
      return false;
    }
  }

  private static final class TooSlow extends RuntimeException {
    private static final long serialVersionUID = 1L;

    TooSlow() {
      super(null, null, false, false);
    }
  }

  /** A text that stops the matcher after too many reads. */
  private static final class Bounded implements CharSequence {
    private final String text;
    private final int[] steps;

    Bounded(final String text) {
      this(text, new int[1]);
    }

    private Bounded(final String text, final int[] steps) {
      this.text = text;
      this.steps = steps;
    }

    @Override
    public int length() {
      return text.length();
    }

    @Override
    public char charAt(final int index) {
      if (++steps[0] > MAX_STEPS) {
        throw new TooSlow();
      }
      return text.charAt(index);
    }

    @Override
    public CharSequence subSequence(final int start, final int end) {
      return new Bounded(text.substring(start, end), steps);
    }

    @Override
    public String toString() {
      return text;
    }
  }
}
